WITH recent_transactions AS (SELECT *, ROUND(amount * 0.9, 2) AS amount_scaled FROM transactions WHERE amount > 2800), transactions_stats AS (SELECT is_flagged, QUARTER(txn_time) AS txn_quarter, ROUND(AVG(amount), 2) AS avg_amount, SUM(CASE WHEN txn_type = 'FEE' THEN 1 ELSE 0 END) AS fee_count FROM recent_transactions GROUP BY is_flagged, QUARTER(txn_time)) SELECT is_flagged, txn_quarter, avg_amount, fee_count FROM transactions_stats;
